  2	 * Principles and competitor notes are example content written for the prototype (a PM would own and edit them);
  3	 * they are not BMW statements.
  4	 */
  5	import type { Category, SeriesId } from "./types";
  6	
  7	export interface SeriesConfig {
  8	  id: SeriesId;
  9	  slug: "1-series" | "5-series" | "7-series";
 10	  name: string;
 11	  /** Code + one-line positioning. */
 12	  segment: string;
 13	  /** L1: principles every profile must respect. */
 14	  principles: { id: string; text: string; owner: string }[];
 15	  /** Competitors to benchmark in the profiles (L2 context). */
 16	  competitors: { name: string; note: string }[];
 17	  /** How much the L3 social test may move a profile's score (share of the total). */
 18	  l3Weight: number;
 19	  /** Categories this series leans on when the AI shapes profiles. */
 20	  focus: Category[];
 21	}
 22	
 23	export const SERIES: SeriesConfig[] = [
 24	  {
 25	    id: "F70",
 26	    slug: "1-series",
 27	    name: "1 Series",
 28	    segment: "F70 · compact entry model, younger buyers",
 29	    principles: [
 30	      { id: "P1", text: "Stays compact: city-friendly footprint and parking.", owner: "PM 1 Series" },
 31	      { id: "P2", text: "Entry price stays within reach of first-time BMW buyers.", owner: "Pricing" },
 32	      { id: "P3", text: "Driving pleasure is never traded for comfort alone.", owner: "Brand" },
 33	    ],
 34	    competitors: [
 35	      { name: "Mercedes-Benz A-Class", note: "Interior ambience and screen-first cockpit" },
 36	      { name: "Audi A3 Sportback", note: "Quality feel, physical climate controls" },
 37	      { name: "VW Golf", note: "Value for money, broad powertrain range" },
 38	    ],
 39	    l3Weight: 0.2,
 40	    focus: ["Digital", "Exterior"],
 41	  },
 42	  {
 43	    id: "G60",
 44	    slug: "5-series",
 45	    name: "5 Series",
 46	    segment: "G60 · business sedan, the volume driver",
 47	    principles: [
 48	      { id: "P1", text: "Business sedan first: comfort and quiet on long trips.", owner: "PM 5 Series" },
 49	      { id: "P2", text: "Every powertrain (ICE, PHEV, BEV) keeps the same core experience.", owner: "Engineering" },
 50	      { id: "P3", text: "Technology must be easy to use without the manual.", owner: "UX" },
 51	    ],
 52	    competitors: [
 53	      { name: "Mercedes-Benz E-Class", note: "Rear comfort, large-screen interior" },
 54	      { name: "Audi A6 / A6 e-tron", note: "Efficiency and charging speed" },
