  1	/* Dixi score for a feature request (0–100) with decision memory.
  2	 *
  3	 *   base   = weighted mean of  demand · market backing · principle fit
  4	 *   memory = past decisions on the same request (same series), from earlier generations:
  5	 *            rejected → penalty that fades with a half-life, lifted when demand has grown enough since ("resurfaced")
  6	 *            kept     → small bonus that fades the same way
  7	 *   score  = base × (1 − penalty) + bonus
  8	 *
  9	 * Pure functions (usable on server and client). The settings store lives in scoring-store.ts (client only).
 10	 * Settings are tuned by the team in /dashboard/settings and stored in this browser for now (Supabase later).
 11	 * The backend agent will apply the same rules before it proposes requests (see docs/architecture/09-scoring-and-memory.md).
 12	 */
 13	import type { MarketScope } from "@/lib/dashboard-data";
 14	import type { Decision } from "./profiles";
 15	import type { Session } from "./sessions";
 16	import type { Category, FeatureRequest, SeriesId } from "./types";
 17	
 18	export interface ScoringSettings {
 19	  /** Relative weights of the three base parts (normalised). */
 20	  wDemand: number;
 21	  wBacking: number;
 22	  wFit: number;
 23	  /** How much a past reject lowers the score at full strength (0–1). */
 24	  rejectPenalty: number;
 25	  /** Bonus for requests kept before (0–1, of 10 points). */
 26	  keepBonus: number;
 27	  /** After this many days a past decision counts half. */
 28	  halfLifeDays: number;
 29	  /** Demand growth since the reject that brings a request back (0.3 = +30 %). */
 30	  resurfaceAt: number;
 31	  /** Hide previously rejected requests instead of only ranking them lower. */
 32	  hideRejected: boolean;
 33	  /** Use memory from every market, or only from the same market. */
 34	  memoryScope: "market" | "all";
 35	}
 36	
 37	export const DEFAULT_SCORING: ScoringSettings = {
 38	  wDemand: 0.6,
 39	  wBacking: 0.25,
 40	  wFit: 0.15,
 41	  rejectPenalty: 0.6,
 42	  keepBonus: 0.5,
 43	  halfLifeDays: 365,
 44	  resurfaceAt: 0.3,
 45	  hideRejected: false,
 46	  memoryScope: "market",
 47	};
 48	
 49	/* ---------- decision memory ---------- */
 50	
 51	export interface MemoryEntry {
 52	  action: "keep" | "reject";
 53	  reason?: string;
 54	  by: string;
 55	  role?: string;
 56	  at: string;
 57	  /** Mentions when the decision was made (to detect growing demand). */
 58	  mentionsAt?: number;
 59	  generationId: string;
 60	  scopeLabel: string;
 61	}
 62	
 63	/** Key that stays stable across data rebuilds: series + request title. */
 64	export const memoryKey = (series: SeriesId, title: string) => `${series}:${title.toLowerCase()}`;
 65	
 66	/** Latest keep/reject per request from earlier generations of this series (and market, unless scope is "all"). */
 67	export function buildMemory(generations: Session[], series: SeriesId, scope: MarketScope, settings: ScoringSettings): Map<string, MemoryEntry> {
 68	  const mem = new Map<string, MemoryEntry>();
 69	  const relevant = generations
 70	    .filter((g) => g.series === series && (settings.memoryScope === "all" || g.scope === scope))
 71	    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
 72	  for (const g of relevant) {
 73	    for (const d of Object.values(g.decisions) as Decision[]) {
 74	      if (d.action !== "keep" && d.action !== "reject") continue;
 75	      const k = memoryKey(series, d.title);
 76	      const prev = mem.get(k);
 77	      if (!prev || prev.at <= d.at)
 78	        mem.set(k, { action: d.action, reason: d.reason, by: d.by, role: d.role, at: d.at, mentionsAt: d.mentionsAt, generationId: g.id, scopeLabel: g.scopeLabel });
 79	    }
 80	  }
 81	  return mem;
 82	}
 83	
 84	/* ---------- the score ---------- */
 85	
 86	export type MemoryState = "rejected" | "resurfaced" | "kept" | null;
 87	
 88	export interface Scored {
 89	  score: number;
 90	  base: number;
 91	  parts: { demand: number; backing: number; fit: number };
 92	  memory: MemoryEntry | null;
 93	  state: MemoryState;
 94	  /** 0–1: how much of the penalty or bonus still applies after the half-life decay. */
 95	  strength: number;
 96	  /** Demand growth since the past decision (null when unknown). */
 97	  growth: number | null;
 98	  hidden: boolean;
 99	}
100	
101	export function scoreRequest(
102	  req: FeatureRequest,
103	  scoped: number,
104	  maxScoped: number,
105	  backingCount: number,
106	  focus: Category[],
107	  memory: Map<string, MemoryEntry>,
108	  s: ScoringSettings,
109	  now = Date.now(),
110	): Scored {
111	  const demand = maxScoped > 0 ? Math.log1p(scoped) / Math.log1p(maxScoped) : 0;
112	  const backing = Math.min(1, backingCount / 2);
113	  const fit = focus.includes(req.category) ? 1 : 0.4;
114	  const wSum = s.wDemand + s.wBacking + s.wFit || 1;
115	  const base = (100 * (s.wDemand * demand + s.wBacking * backing + s.wFit * fit)) / wSum;
116	
117	  const m = memory.get(memoryKey(req.series, req.title)) ?? null;
118	  let state: MemoryState = null;
119	  let strength = 0;
120	  let growth: number | null = null;
121	  let score = base;
122	  if (m) {
123	    const days = Math.max(0, (now - Date.parse(m.at)) / 86_400_000);
124	    strength = Math.pow(0.5, days / Math.max(1, s.halfLifeDays));
125	    growth = m.mentionsAt ? (scoped - m.mentionsAt) / m.mentionsAt : null;
126	    if (m.action === "reject") {
127	      const resurfaced = growth !== null && growth >= s.resurfaceAt;
128	      state = resurfaced ? "resurfaced" : "rejected";
129	      if (!resurfaced) score = base * (1 - s.rejectPenalty * strength);
130	    } else {
131	      state = "kept";
132	      score = Math.min(100, base + 10 * s.keepBonus * strength);
133	    }
134	  }
135	  return {
136	    score: Math.round(score),
137	    base: Math.round(base),
138	    parts: { demand, backing, fit },
139	    memory: m,
140	    state,
141	    strength,
142	    growth,
143	    hidden: s.hideRejected && state === "rejected",
144	  };
145	}
  1	"use client";
  2	
  3	/* Scoring settings store: localStorage, reactive across tabs. Client only; the rules themselves are in scoring.ts. */
  4	import { useSyncExternalStore } from "react";
  5	import { DEFAULT_SCORING, type ScoringSettings } from "./scoring";
  6	
  7	const KEY = "dixi:scoring";
  8	const EVENT = "dixi:scoring";
  9	let cacheRaw: string | null | undefined;
 10	let cache: ScoringSettings = DEFAULT_SCORING;
 11	
 12	function read(): ScoringSettings {
 13	  let raw: string | null = null;
 14	  try {
 15	    raw = localStorage.getItem(KEY);
 16	  } catch {
 17	    /* storage blocked */
 18	  }
 19	  if (raw !== cacheRaw) {
 20	    cacheRaw = raw;
 21	    try {
 22	      cache = { ...DEFAULT_SCORING, ...(raw ? (JSON.parse(raw) as Partial<ScoringSettings>) : {}) };
 23	    } catch {
 24	      cache = DEFAULT_SCORING;
 25	    }
 26	  }
 27	  return cache;
 28	}
 29	
 30	export function saveScoring(s: ScoringSettings) {
 31	  try {
 32	    localStorage.setItem(KEY, JSON.stringify(s));
 33	  } catch {
 34	    /* storage blocked */
 35	  }
 36	  window.dispatchEvent(new Event(EVENT));
 37	}
 38	
 39	function subscribe(cb: () => void) {
 40	  window.addEventListener(EVENT, cb);
 41	  window.addEventListener("storage", cb);
 42	  return () => {
 43	    window.removeEventListener(EVENT, cb);
 44	    window.removeEventListener("storage", cb);
 45	  };
 46	}
 47	
 48	export const useScoring = () => useSyncExternalStore(subscribe, read, () => DEFAULT_SCORING);
 49

