  1	/* Pipeline logic: market scoping, urgency, PM decisions, profile building and the layer score.
  2	 * Pure functions, shared by the client components. Deterministic: the same decisions always build the same profiles.
  3	 */
  4	import type { MarketScope } from "@/lib/dashboard-data";
  5	import type { SeriesConfig } from "./series";
  6	import type { Category, FeatureRequest, MarketSignal, SeriesData } from "./types";
  7	
  8	/* ---------- scope + urgency ---------- */
  9	
 10	/** Feedback records for this series in the chosen market; 0 means we have no comments there. */
 11	export function marketVolume(data: SeriesData, scope: MarketScope): number {
 12	  if (scope === "ALL") return Object.values(data.feedbackByMarket).reduce((a, b) => a + (b ?? 0), 0);
 13	  return data.feedbackByMarket[scope] ?? 0;
 14	}
 15	
 16	/** Mentions of a request in scope. Falls back to all markets when the market has no comments at all. */
 17	export function scopedMentions(req: FeatureRequest, scope: MarketScope, fallback: boolean): number {
 18	  if (scope === "ALL" || fallback) return req.mentions;
 19	  return req.byMarket[scope] ?? 0;
 20	}
 21	
 22	export type Urgency = "high" | "medium" | "low";
 23	export const URGENCY_RULE = { high: 50, medium: 20 } as const;
 24	export const urgencyOf = (mentions: number): Urgency =>
 25	  mentions >= URGENCY_RULE.high ? "high" : mentions >= URGENCY_RULE.medium ? "medium" : "low";
 26	
 27	/* ---------- PM decisions ---------- */
 28	
 29	export interface Decision {
 30	  requestId: string;
 31	  title: string;
 32	  /** keep/reject a customer request, or put a trend/competitor feature on the wishlist. */
 33	  action: "keep" | "reject" | "wish";
 34	  /** Required for a reject. */
 35	  reason?: string;
 36	  /** Who decided (name) and their role: from the local "who is deciding" identity until there is a login. */
 37	  by: string;
 38	  role?: string;
 39	  /** When, ISO timestamp. */
 40	  at: string;
 41	  /** Customer mentions of the request at decision time, so later generations can see if demand grew. */
 42	  mentionsAt?: number;
 43	}
 44	
 45	export type Decisions = Record<string, Decision>;
 46	
 47	export const REJECT_REASONS = [
 48	  "Conflicts with a BMW principle",
 49	  "Too costly for the benefit",
 50	  "Already on the option list",
 51	  "Too few customers ask for it",
 52	  "Not right for this market",
 53	] as const;
 54	
 55	/* ---------- profiles ---------- */
 56	
 57	export interface Profile {
 58	  id: string;
 59	  name: string;
 60	  tagline: string;
 61	  /** `priority` = the PM's position for this request (1 = most important). */
 62	  requests: (FeatureRequest & { scoped: number; priority: number })[];
 63	  /** Wishlist items (trends, competitor features) this profile takes on. */
 64	  wishes: MarketSignal[];
 65	  /** Market signals backing the requests in this profile. */
 66	  backing: MarketSignal[];
 67	  why: string[];
 68	  score: { l1: number; l2: number; l3: number | null; total: number };
 69	}
 70	
 71	interface Archetype {
 72	  id: string;
 73	  name: string;
 74	  tagline: string;
 75	  /** Higher = picked first. */
 76	  rank: (r: FeatureRequest) => number;
 77	  /** Wishlist categories this archetype takes on. */
 78	  wishCats: Category[];
 79	}
 80	
 81	const fixShare = (r: FeatureRequest) => (r.types.difficult + r.types.defect) / Math.max(1, r.types.wants + r.types.difficult + r.types.defect);
 82	const inCats = (cats: Category[]) => (r: FeatureRequest) => (cats.includes(r.category) ? 1 : 0);
 83	
 84	const ARCHETYPES: Archetype[] = [
 85	  {
 86	    id: "fix",
 87	    name: "Fix the basics",
 88	    tagline: "Remove what annoys today's owners before adding anything new.",
 89	    rank: (r) => fixShare(r),
 90	    wishCats: [],
 91	  },
 92	  {
 93	    id: "tech",
 94	    name: "Tech-forward",
 95	    tagline: "Lead on software, assistance and powertrain.",
 96	    rank: inCats(["Digital", "Powertrain"]),
 97	    wishCats: ["Digital", "Powertrain"],
 98	  },
 99	  {
100	    id: "comfort",
101	    name: "Comfort & craft",
102	    tagline: "A calmer, better-made cabin and a cleaner design.",
103	    rank: inCats(["Interior", "Exterior"]),
104	    wishCats: ["Interior", "Exterior"],
105	  },
106	];
107	
108	const MAX_PER_PROFILE = 6;
109	export const MIN_KEPT_TO_BUILD = 3;
110	
111	/** Signals for this series and market ("ALL" = every market; markets without research get none). */
112	export function signalsFor(all: MarketSignal[], series: FeatureRequest["series"], scope: MarketScope): MarketSignal[] {
113	  return all.filter((s) => s.series.includes(series) && (scope === "ALL" || (s.markets as string[]).includes(scope)));
114	}
115	
116	/** `kept` must be in the PM's priority order: position 1 first. The order decides which requests a profile takes
117	 *  (after the profile's own theme) and the order they are listed in. */
118	export function buildProfiles(
119	  kept: FeatureRequest[],
120	  cfg: SeriesConfig,
121	  scope: MarketScope,
122	  fallback: boolean,
123	  social: Record<string, number> | null,
124	  wishlist: MarketSignal[] = [],
125	  signals: MarketSignal[] = [],
126	): Profile[] {
127	  const scopedKept = kept.map((r, i) => ({ ...r, scoped: scopedMentions(r, scope, fallback), priority: i + 1 }));
128	  const keptTotal = scopedKept.reduce((a, r) => a + r.scoped, 0) || 1;
129	
130	  return ARCHETYPES.map((a) => {
131	    const picked = [...scopedKept]
132	      .sort((x, y) => a.rank(y) - a.rank(x) || x.priority - y.priority)
133	      .slice(0, Math.min(MAX_PER_PROFILE, Math.max(MIN_KEPT_TO_BUILD, Math.ceil(scopedKept.length * 0.6))))
134	      .sort((x, y) => x.priority - y.priority);
135	
136	    const covered = picked.reduce((s, r) => s + r.scoped, 0);
137	    const inFocus = picked.filter((r) => cfg.focus.includes(r.category)).length;
138	    /* L1 also rewards following the PM's priority order: the PM's ranking is a human principle for this decision. */
139	    const prioFit = picked.reduce((sum, r) => sum + 1 / r.priority, 0) / scopedKept.slice(0, picked.length).reduce((sum, r) => sum + 1 / r.priority, 0);
140	    const l1 = 0.5 + 0.25 * (inFocus / Math.max(1, picked.length)) + 0.25 * prioFit;
141	    const l2 = covered / keptTotal;
142	    const l3 = social ? social[a.id] ?? null : null;
143	    const w3 = l3 === null ? 0 : cfg.l3Weight;
144	    const w1 = 0.45 * (1 - w3);
145	    const w2 = 1 - w1 - w3;
146	    const total = w1 * l1 + w2 * l2 + w3 * (l3 ?? 0);
147	
148	    const wishes = wishlist.filter((w) => a.wishCats.includes(w.category));
149	    const titles = new Set(picked.map((r) => r.title));
150	    const backing = signals.filter((sg) => sg.relatesTo.some((t) => titles.has(t)));
151	    const cats = [...new Set(picked.map((r) => r.category))];
152	    const left = scopedKept.filter((r) => !picked.includes(r));
153	    const tops = picked.filter((r) => r.priority <= 3).map((r) => `#${r.priority}`);
154	    const why = [
155	      `Covers ${covered.toLocaleString("en")} customer mentions, ${Math.round(l2 * 100)}% of everything you kept.`,
156	      `${inFocus} of ${picked.length} requirements match the ${cfg.name}'s focus on ${cfg.focus.join(" and ")} (BMW principles).`,
157	      tops.length ? `Takes your top priorities ${tops.join(", ")}.` : "Takes none of your top-3 priorities.",
158	      `Leans on ${cats.join(", ")}.`,
159	      left.length ? `Leaves out ${left.slice(0, 2).map((r) => r.title).join(" and ")}${left.length > 2 ? ` and ${left.length - 2} more` : ""}.` : "Includes every request you kept.",
160	    ];
161	    if (backing.length) why.push(`${backing.length} competitor feature${backing.length > 1 ? "s" : ""} or trend${backing.length > 1 ? "s" : ""} back these requests.`);
162	    if (wishes.length) why.push(`Adds ${wishes.length} item${wishes.length > 1 ? "s" : ""} from your wishlist: ${wishes.map((w) => w.title).join(", ")}.`);
163	    if (fallback) why.push("No comments from this market for this series: built on all markets, so confidence is lower.");
164	
165	    return { id: a.id, name: a.name, tagline: a.tagline, requests: picked, wishes, backing, why, score: { l1, l2, l3, total } };
166	  }).sort((x, y) => y.score.total - x.score.total);
167	}
168	
169	/** Draft SMART target for a requirement. A PM edits it later; it is a starting point, not a commitment. */
170	export function draftTarget(r: FeatureRequest & { scoped: number }): string {
171	  const t = `“${r.title}”`;
172	  if (r.types.defect > r.types.wants && r.types.defect >= r.types.difficult)
173	    return `${t}: halve defect reports in this area within 12 months of launch (baseline ${r.scoped} mentions).`;
174	  if (r.types.difficult > r.types.wants) return `${t}: halve ease-of-use complaints in this area within 12 months of launch (baseline ${r.scoped} mentions).`;
175	  return `${t}: available at launch; wishes for it drop by half within 12 months (baseline ${r.scoped} mentions).`;
176	}
177	
178	/** Re-score saved profiles once a social test (L3) has run, and re-rank them. */
179	export function applySocial(profiles: Profile[], social: Record<string, number> | null, l3Weight: number): Profile[] {
180	  return profiles
181	    .map((p) => {
182	      const l3 = social ? social[p.id] ?? null : null;
183	      const w3 = l3 === null ? 0 : l3Weight;
184	      const w1 = 0.45 * (1 - w3);
185	      const w2 = 1 - w1 - w3;
186	      return { ...p, score: { ...p.score, l3, total: w1 * p.score.l1 + w2 * p.score.l2 + w3 * (l3 ?? 0) } };
187	    })
188	    .sort((a, b) => b.score.total - a.score.total);
189	}
  1	/* Generations (stored as sessions): every "Build profiles" saves a snapshot, so a PM can reopen earlier generations later.
  2	 * Stored in this browser for now (localStorage); moves to Supabase with the backend.
  3	 */
  4	import type { MarketScope } from "@/lib/dashboard-data";
  5	import type { Campaign } from "./analytics";
  6	import type { Decisions, Profile } from "./profiles";
  7	import type { SeriesId } from "./types";
  8	
  9	export interface Session {
 10	  id: string;
 11	  createdAt: string;
 12	  /** Who built this generation. */
 13	  createdBy?: string;
 14	  createdByRole?: string;
 15	  scope: MarketScope;
 16	  scopeLabel: string;
 17	  series: SeriesId;
 18	  seriesName: string;
 19	  slug: string;
 20	  profiles: Profile[];
 21	  decisions: Decisions;
 22	  order: string[];
 23	  campaigns: Campaign[] | null;
 24	}
 25	
 26	const KEY = "dixi:sessions";
 27	const MAX = 30;
 28	
 29	export function readSessions(): Session[] {
 30	  try {
 31	    return (JSON.parse(localStorage.getItem(KEY) ?? "[]") as Session[]).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
 32	  } catch {
 33	    return [];
 34	  }
 35	}
 36	
 37	function write(list: Session[]) {
 38	  try {
 39	    localStorage.setItem(KEY, JSON.stringify(list.slice(0, MAX)));
 40	  } catch {
 41	    /* storage full or blocked: sessions stay for this visit only */
 42	  }
 43	}
 44	
 45	export function saveSession(s: Session) {
 46	  write([s, ...readSessions().filter((x) => x.id !== s.id)]);
 47	}
 48	
 49	export function updateSession(id: string, patch: Partial<Session>) {
 50	  write(readSessions().map((s) => (s.id === id ? { ...s, ...patch } : s)));
 51	}
 52	
 53	export function deleteSession(id: string) {
 54	  write(readSessions().filter((s) => s.id !== id));
 55	}
 56	
 57	export const newSessionId = () => `G-${Date.now().toString(36).toUpperCase()}`;
 58	
 59	/** The generation's own dashboard. */
 60	export const generationHref = (id: string) => `/dashboard/generations#${id}`;
 61	/** Back into the pipeline with this generation's decisions and priority loaded, to edit and rebuild. */
 62	export const editHref = (s: Pick<Session, "scope" | "slug" | "id">) => `/dashboard/${s.scope.toLowerCase()}/${s.slug}#session=${s.id}`;
 63	
 64	export const sessionTime = (iso: string) => new Date(iso).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
  1	/* L3 social test, simulated: each profile is "posted" and tracked for 14 days.
  2	 * Deterministic per market + series + profile, so the same inputs always show the same curves.
  3	 * Replace with real post metrics once a social channel is connected.
  4	 */
  5	
  6	export interface DayPoint {
  7	  day: number;
  8	  impressions: number;
  9	  /** Engagements / impressions, 0–1. */
 10	  engagement: number;
 11	  /** Share of positive reactions, 0–1. */
 12	  positive: number;
 13	}
 14	
 15	export interface Campaign {
 16	  profileId: string;
 17	  days: DayPoint[];
 18	  impressions: number;
 19	  engagement: number;
 20	  positive: number;
 21	  shares: number;
 22	  /** 0–1 summary used as the L3 score: mix of engagement and positive share. */
 23	  l3: number;
 24	}
 25	
 26	export const CAMPAIGN_DAYS = 14;
 27	
 28	function rng(seed: string) {
 29	  let h = 2166136261;
 30	  for (const ch of seed) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
 31	  return () => {
 32	    h = Math.imul(h ^ (h >>> 15), 2246822507);
 33	    h = Math.imul(h ^ (h >>> 13), 3266489909);
 34	    return ((h ^= h >>> 16) >>> 0) / 4294967296;
 35	  };
 36	}
 37	
 38	export function simulateCampaigns(profileIds: string[], seed: string): Campaign[] {
 39	  return profileIds.map((id) => {
 40	    const r = rng(`${seed}:${id}`);
 41	    const base = 0.025 + r() * 0.035; // starting engagement 2.5–6 %
 42	    const drift = (r() - 0.4) * 0.003; // some profiles gain, some fade
 43	    const reach = 8000 + r() * 9000;
 44	    const pos = 0.45 + r() * 0.35;
 45	    const days: DayPoint[] = Array.from({ length: CAMPAIGN_DAYS }, (_, d) => {
 46	      const noise = (r() - 0.5) * 0.006;
 47	      return {
 48	        day: d + 1,
 49	        impressions: Math.round(reach * (1 + d * 0.12) * (0.85 + r() * 0.3)),
 50	        engagement: Math.max(0.005, base + drift * d + noise),
 51	        positive: Math.min(0.95, Math.max(0.2, pos + (r() - 0.5) * 0.08 + drift * d * 4)),
 52	      };
 53	    });
 54	    const impressions = days.reduce((s, x) => s + x.impressions, 0);
 55	    const engagement = days.reduce((s, x) => s + x.engagement * x.impressions, 0) / impressions;
 56	    const positive = days.reduce((s, x) => s + x.positive * x.impressions, 0) / impressions;
 57	    return {
 58	      profileId: id,
 59	      days,
 60	      impressions,
 61	      engagement,
 62	      positive,
 63	      shares: Math.round(impressions * engagement * 0.12),
 64	      l3: Math.min(1, 0.5 * Math.min(1, engagement / 0.08) + 0.5 * positive),
 65	    };
 66	  });
 67	}
 68	
 69	/** Last-7-days engagement vs the first 7: who is gaining momentum. */
 70	export function momentum(c: Campaign): number {
 71	  const half = Math.floor(c.days.length / 2);
 72	  const avg = (xs: DayPoint[]) => xs.reduce((s, x) => s + x.engagement, 0) / xs.length;
 73	  return avg(c.days.slice(half)) / avg(c.days.slice(0, half)) - 1;
 74	}

