159	      left.length ? `Leaves out ${left.slice(0, 2).map((r) => r.title).join(" and ")}${left.length > 2 ? ` and ${left.length - 2} more` : ""}.` : "Includes every request you kept.",
160	    ];
161	    if (backing.length) why.push(`${backing.length} competitor feature${backing.length > 1 ? "s" : ""} or trend${backing.length > 1 ? "s" : ""} back these requests.`);
162	    if (wishes.length) why.push(`Adds ${wishes.length} item${wishes.length > 1 ? "s" : ""} from your wishlist: ${wishes.map((w) => w.title).join(", ")}.`);
163	    if (fallback) why.push("No comments from this market for this series: built on all markets, so confidence is lower.");
164	
165	    return { id: a.id, name: a.name, tagline: a.tagline, requests: picked, wishes, backing, why, score: { l1, l2, l3, total } };
166	  }).sort((x, y) => y.score.total - x.score.total);
167	}
168	
169	/** Draft SMART target for a requirement. A PM edits it later; it is a starting point, not a commitment. */
170	export function draftTarget(r: FeatureRequest & { scoped: number }): string {
171	  const t = `“${r.title}”`;
172	  if (r.types.defect > r.types.wants && r.types.defect >= r.types.difficult)
173	    return `${t}: halve defect reports in this area within 12 months of launch (baseline ${r.scoped} mentions).`;
174	  if (r.types.difficult > r.types.wants) return `${t}: halve ease-of-use complaints in this area within 12 months of launch (baseline ${r.scoped} mentions).`;
175	  return `${t}: available at launch; wishes for it drop by half within 12 months (baseline ${r.scoped} mentions).`;
176	}
177	
178	/** Re-score saved profiles once a social test (L3) has run, and re-rank them. */
179	export function applySocial(profiles: Profile[], social: Record<string, number> | null, l3Weight: number): Profile[] {
180	  return profiles
181	    .map((p) => {
182	      const l3 = social ? social[p.id] ?? null : null;
183	      const w3 = l3 === null ? 0 : l3Weight;
184	      const w1 = 0.45 * (1 - w3);
185	      const w2 = 1 - w1 - w3;
186	      return { ...p, score: { ...p.score, l3, total: w1 * p.score.l1 + w2 * p.score.l2 + w3 * (l3 ?? 0) } };
187	    })
188	    .sort((a, b) => b.score.total - a.score.total);
189	}
  1	/* Generations (stored as sessions): every "Build profiles" saves a snapshot, so a PM can reopen earlier generations later.
  2	 * Stored in this browser for now (localStorage); moves to Supabase with the backend.
  3	 */
  4	import type { MarketScope } from "@/lib/dashboard-data";
  5	import type { Campaign } from "./analytics";
  6	import type { Decisions, Profile } from "./profiles";
  7	import type { SeriesId } from "./types";
  8	
  9	export interface Session {
 10	  id: string;
 11	  createdAt: string;
 12	  /** Who built this generation. */
 13	  createdBy?: string;
 14	  createdByRole?: string;
 15	  scope: MarketScope;
 16	  scopeLabel: string;
 17	  series: SeriesId;
 18	  seriesName: string;
 19	  slug: string;
 20	  profiles: Profile[];
 21	  decisions: Decisions;
 22	  order: string[];
 23	  campaigns: Campaign[] | null;
 24	}
 25	
 26	const KEY = "dixi:sessions";
 27	const MAX = 30;
 28	
 29	export function readSessions(): Session[] {
 30	  try {
 31	    return (JSON.parse(localStorage.getItem(KEY) ?? "[]") as Session[]).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
 32	  } catch {
 33	    return [];
 34	  }
 35	}
 36	
 37	function write(list: Session[]) {
 38	  try {
 39	    localStorage.setItem(KEY, JSON.stringify(list.slice(0, MAX)));
 40	  } catch {
 41	    /* storage full or blocked: sessions stay for this visit only */
 42	  }
 43	}
 44	
 45	export function saveSession(s: Session) {
 46	  write([s, ...readSessions().filter((x) => x.id !== s.id)]);
 47	}
 48	
 49	export function updateSession(id: string, patch: Partial<Session>) {
 50	  write(readSessions().map((s) => (s.id === id ? { ...s, ...patch } : s)));
 51	}
 52	
 53	export function deleteSession(id: string) {
 54	  write(readSessions().filter((s) => s.id !== id));
 55	}
 56	
 57	export const newSessionId = () => `G-${Date.now().toString(36).toUpperCase()}`;
 58	
 59	/** The generation's own dashboard. */
 60	export const generationHref = (id: string) => `/dashboard/generations#${id}`;
 61	/** Back into the pipeline with this generation's decisions and priority loaded, to edit and rebuild. */
 62	export const editHref = (s: Pick<Session, "scope" | "slug" | "id">) => `/dashboard/${s.scope.toLowerCase()}/${s.slug}#session=${s.id}`;
 63	
 64	export const sessionTime = (iso: string) => new Date(iso).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
  1	/* L3 social test, simulated: each profile is "posted" and tracked for 14 days.
  2	 * Deterministic per market + series + profile, so the same inputs always show the same curves.
  3	 * Replace with real post metrics once a social channel is connected.
  4	 */
  5	
  6	export interface DayPoint {
  7	  day: number;
  8	  impressions: number;
  9	  /** Engagements / impressions, 0–1. */
 10	  engagement: number;
 11	  /** Share of positive reactions, 0–1. */
 12	  positive: number;
 13	}
 14	
 15	export interface Campaign {
 16	  profileId: string;
 17	  days: DayPoint[];
 18	  impressions: number;
 19	  engagement: number;
 20	  positive: number;
 21	  shares: number;
 22	  /** 0–1 summary used as the L3 score: mix of engagement and positive share. */
 23	  l3: number;
 24	}
 25	
 26	export const CAMPAIGN_DAYS = 14;
 27	
 28	function rng(seed: string) {
 29	  let h = 2166136261;
 30	  for (const ch of seed) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
 31	  return () => {
 32	    h = Math.imul(h ^ (h >>> 15), 2246822507);
 33	    h = Math.imul(h ^ (h >>> 13), 3266489909);
 34	    return ((h ^= h >>> 16) >>> 0) / 4294967296;
 35	  };
 36	}
 37	
 38	export function simulateCampaigns(profileIds: string[], seed: string): Campaign[] {
 39	  return profileIds.map((id) => {
 40	    const r = rng(`${seed}:${id}`);
 41	    const base = 0.025 + r() * 0.035; // starting engagement 2.5–6 %
 42	    const drift = (r() - 0.4) * 0.003; // some profiles gain, some fade
 43	    const reach = 8000 + r() * 9000;
 44	    const pos = 0.45 + r() * 0.35;
 45	    const days: DayPoint[] = Array.from({ length: CAMPAIGN_DAYS }, (_, d) => {
 46	      const noise = (r() - 0.5) * 0.006;
 47	      return {
 48	        day: d + 1,
 49	        impressions: Math.round(reach * (1 + d * 0.12) * (0.85 + r() * 0.3)),
 50	        engagement: Math.max(0.005, base + drift * d + noise),
 51	        positive: Math.min(0.95, Math.max(0.2, pos + (r() - 0.5) * 0.08 + drift * d * 4)),
 52	      };
 53	    });
 54	    const impressions = days.reduce((s, x) => s + x.impressions, 0);
 55	    const engagement = days.reduce((s, x) => s + x.engagement * x.impressions, 0) / impressions;
 56	    const positive = days.reduce((s, x) => s + x.positive * x.impressions, 0) / impressions;
 57	    return {
 58	      profileId: id,
 59	      days,
 60	      impressions,
 61	      engagement,
 62	      positive,
 63	      shares: Math.round(impressions * engagement * 0.12),
 64	      l3: Math.min(1, 0.5 * Math.min(1, engagement / 0.08) + 0.5 * positive),
 65	    };
 66	  });
 67	}
 68	
 69	/** Last-7-days engagement vs the first 7: who is gaining momentum. */
 70	export function momentum(c: Campaign): number {
 71	  const half = Math.floor(c.days.length / 2);
 72	  const avg = (xs: DayPoint[]) => xs.reduce((s, x) => s + x.engagement, 0) / xs.length;
 73	  return avg(c.days.slice(half)) / avg(c.days.slice(0, half)) - 1;
 74	}

