 34	import { SignalsPanel } from "./SignalsPanel";
 35	
 36	type Stage = "analysing" | "review" | "building" | "profiles";
 37	
 38	const STEPS: { id: Stage; label: string }[] = [
 39	  { id: "analysing", label: "AI analysis" },
 40	  { id: "review", label: "Your decisions" },
 41	  { id: "building", label: "Build profiles" },
 42	  { id: "profiles", label: "Dashboard" },
 43	];
