 45	
 46	/* Decisions live in the browser for now (per market + series). */
 47	const storageKey = (scope: MarketScope, series: string) => `dixi:decisions:${scope}:${series}`;
 48	const priorityKey = (scope: MarketScope, series: string) => `dixi:priority:${scope}:${series}`;
 49	function readJson<T>(key: string, fallback: T): T {
 50	  try {
 51	    return (JSON.parse(localStorage.getItem(key) ?? "null") as T) ?? fallback;
 52	  } catch {
 53	    return fallback;
 54	  }
 55	}
 56	function writeJson(key: string, value: unknown) {
 57	  try {
 58	    localStorage.setItem(key, JSON.stringify(value));
 59	  } catch {
 60	    /* storage blocked: keep it in memory */
 61	  }
 62	}
 63	function readDecisions(key: string): Decisions {
 64	  try {
 65	    return JSON.parse(localStorage.getItem(key) ?? "{}") as Decisions;
 66	  } catch {
 67	    return {};
 68	  }
 69	}
 70	function writeDecisions(key: string, d: Decisions) {
 71	  try {
 72	    localStorage.setItem(key, JSON.stringify(d));
 73	  } catch {
 74	    /* storage blocked: decisions stay in memory */
 75	  }
 76	}
 77	
 78	export function Pipeline({
 79	  scope,
 80	  cfg,
 81	  data,
 82	  origin,
 83	  images,
 84	}: {
 85	  scope: MarketScope;
 86	  cfg: SeriesConfig;
 87	  data: SeriesData;
 88	  origin: "bmw" | "example";
 89	  images?: { front: CarImage; second: CarImage };
 90	}) {
 91	  const scopeLabel = scope === "ALL" ? "all markets" : marketById(scope).name;
 92	  const volume = marketVolume(data, scope);
 93	  const fallback = scope !== "ALL" && volume === 0;
 94	  const key = storageKey(scope, cfg.id);
 95	
 96	  const [stage, setStage] = useState<Stage>("analysing");
 97	  const [decisions, setDecisions] = useState<Decisions>({});
 98	  const [category, setCategory] = useState<Category | "All">("All");
 99	  const [urgency, setUrgency] = useState<Urgency | "all">("all");
100	  const [rejecting, setRejecting] = useState<FeatureRequest | null>(null);
101	  const router = useRouter();
102	  const [focus, setFocus] = useState<string | null>(null);
103	  /** The PM's priority order (request ids). Empty = default order by mentions. */
104	  const [order, setOrder] = useState<string[]>([]);
105	  const [backedOnly, setBackedOnly] = useState(false);
106	  const [details, setDetails] = useState<FeatureRequest | null>(null);
107	
108	  /* L2 market signals: the last live run of the research agent (backend) for this market + series, else the saved research. */
109	  const research = useResearch(scope, cfg.id);
110	  const signals = useMemo(
111	    () => signalsFor(research.result?.signals ?? MARKET_SIGNALS, cfg.id, scope),
112	    [research.result, cfg.id, scope],
113	  );
114	  const signalsByTitle = useMemo(() => {
115	    const m = new Map<string, MarketSignal[]>();
116	    signals.forEach((sg) => sg.relatesTo.forEach((t) => m.set(t, [...(m.get(t) ?? []), sg])));
117	    return m;
118	  }, [signals]);
119	  const focusTitles = new Set(signals.find((sg) => sg.id === focus)?.relatesTo ?? []);
120	
121	  /* Saved decisions are restored when the analysis finishes (client only, so the server HTML stays stable). */
122	  /* Decision memory: earlier generations, read when the list opens. */
123	  const [generations, setGenerations] = useState<Session[]>([]);
124	  const [showHidden, setShowHidden] = useState(false);
125	  const scoring = useScoring();
126	  const memory = useMemo(() => buildMemory(generations, cfg.id, scope, scoring), [generations, cfg.id, scope, scoring]);
127	
128	  const finishAnalysis = useCallback(() => {
129	    setGenerations(readSessions());
130	    setDecisions(readDecisions(key));
131	    setOrder(readJson<string[]>(priorityKey(scope, cfg.id), []));
132	    setStage("review");
133	  }, [key, scope, cfg.id]);
134	
135	  const decide = useCallback(
136	    (item: { id: string; title: string }, action: Decision["action"], reason?: string, mentionsAt?: number) =>
137	      setDecisions((prev) => {
138	        const who = currentUser();
139	        const next = {
140	          ...prev,
141	          [item.id]: { requestId: item.id, title: item.title, action, reason, mentionsAt, by: who.name, role: who.role, at: new Date().toISOString() },
142	        };
143	        writeDecisions(key, next);
144	        return next;
145	      }),
146	    [key],
147	  );
148	  const undo = useCallback(
149	    (id: string) =>
150	      setDecisions((prev) => {
151	        const next = { ...prev };
152	        delete next[id];
153	        writeDecisions(key, next);
154	        return next;
155	      }),
156	    [key],
157	  );
158	
159	  const rows = useMemo(
160	    () =>
161	      data.requests
162	        .map((r) => ({ req: r, scoped: scopedMentions(r, scope, fallback) }))
163	        .filter((x) => x.scoped > 0)
164	        .map((x, _i, all) => {
165	          const max = Math.max(...all.map((y) => y.scoped));
166	          const scored = scoreRequest(x.req, x.scoped, max, signalsByTitle.get(x.req.title)?.length ?? 0, cfg.focus, memory, scoring);
167	          return { ...x, urgency: urgencyOf(x.scoped), scored };
168	        })
169	        /* Default order = Dixi score (demand, market backing, principle fit, decision memory). The PM's drag order wins. */
170	        .sort((a, b) => {
171	          const ia = order.indexOf(a.req.id);
172	          const ib = order.indexOf(b.req.id);
173	          if (ia !== -1 || ib !== -1) return (ia === -1 ? Infinity : ia) - (ib === -1 ? Infinity : ib);
174	          return b.scored.score - a.scored.score || b.scoped - a.scoped;
175	        }),
176	    [data.requests, scope, fallback, order, signalsByTitle, cfg.focus, memory, scoring],
177	  );
178	
179	  /* Reordering works on the full list, so moving inside a filtered view keeps everything else in place. */
180	  const saveOrder = (ids: string[]) => {
181	    setOrder(ids);
182	    writeJson(priorityKey(scope, cfg.id), ids);
183	  };
184	  /* Feedback while reordering: the dragged row dims, the moved row flashes, and rows slide to their new place (FLIP). */
185	  /* Pointer-based dragging (mouse, trackpad and touch): the row follows the pointer, a line shows where it lands. */
186	  const [drag, setDrag] = useState<{ id: string; startY: number; dy: number; target: string | null; where: "before" | "after" } | null>(null);
187	  const [flash, setFlash] = useState<string | null>(null);
188	  const flashTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
189	  const markMoved = (id: string) => {
190	    setFlash(id);
191	    if (flashTimer.current) clearTimeout(flashTimer.current);
192	    flashTimer.current = setTimeout(() => setFlash(null), 900);
193	  };
194	  const listRef = useRef<HTMLUListElement>(null);
195	  const positions = useRef(new Map<string, number>());
196	  const orderKey = rows.map((r) => r.req.id).join();
197	  useLayoutEffect(() => {
198	    const ul = listRef.current;
199	    if (!ul) return;
200	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
201	    const next = new Map<string, number>();
202	    ul.querySelectorAll<HTMLElement>("[data-req]").forEach((el) => {
203	      const id = el.dataset.req!;
204	      const top = el.getBoundingClientRect().top;
205	      next.set(id, top);
206	      const before = positions.current.get(id);
207	      if (!reduce && before !== undefined && Math.abs(before - top) > 1) {
208	        el.animate([{ transform: `translateY(${before - top}px)` }, { transform: "translateY(0)" }], { duration: 260, easing: "cubic-bezier(.2,.8,.2,1)" });
209	      }
210	    });
211	    positions.current = next;
212	  }, [orderKey]);
213	
214	  const moveBefore = (dragged: string, target: string, where: "before" | "after" = "before") => {
215	    const ids = rows.map((r) => r.req.id).filter((id) => id !== dragged);
216	    ids.splice(ids.indexOf(target) + (where === "after" ? 1 : 0), 0, dragged);
217	    saveOrder(ids);
218	    markMoved(dragged);
219	  };
220	  const moveStep = (id: string, dir: -1 | 1, visibleIds: string[]) => {
221	    const neighbour = visibleIds[visibleIds.indexOf(id) + dir];
222	    if (!neighbour) return;
223	    const ids = rows.map((r) => r.req.id);
224	    const a = ids.indexOf(id);
225	    const b = ids.indexOf(neighbour);
226	    [ids[a], ids[b]] = [ids[b], ids[a]];
227	    saveOrder(ids);
228	    markMoved(id);
229	  };
230	  const startDrag = (id: string, e: React.PointerEvent) => {
231	    if (e.button !== 0) return;
232	    e.preventDefault();
233	    setDrag({ id, startY: e.clientY, dy: 0, target: null, where: "before" });
234	  };
235	  useEffect(() => {
236	    if (!drag) return;
237	    const id = drag.id;
238	    const startY = drag.startY;
239	    let last: { target: string | null; where: "before" | "after" } = { target: null, where: "before" };
240	    let scrolled = 0;
241	    const onMove = (e: PointerEvent) => {
242	      if (e.clientY < 90) {
243	        window.scrollBy(0, -14);
244	        scrolled -= 14;
245	      } else if (e.clientY > window.innerHeight - 110) {
246	        window.scrollBy(0, 14);
247	        scrolled += 14;
248	      }
249	      const others = [...(listRef.current?.querySelectorAll<HTMLElement>("[data-req]") ?? [])].filter((el) => el.dataset.req !== id);
250	      const below = others.find((el) => {
251	        const r = el.getBoundingClientRect();
252	        return e.clientY < r.top + r.height / 2;
253	      });
254	      last = below ? { target: below.dataset.req!, where: "before" } : { target: others.at(-1)?.dataset.req ?? null, where: "after" };
255	      setDrag((d) => (d ? { ...d, dy: e.clientY - startY + scrolled, ...last } : d));
256	    };
257	    const onUp = () => {
258	      const el = listRef.current?.querySelector<HTMLElement>(`[data-req="${id}"]`);
259	      if (el) positions.current.set(id, el.getBoundingClientRect().top); // slide from where it was dropped
260	      setDrag(null);
261	      if (last.target) moveBefore(id, last.target, last.where);
262	    };
263	    window.addEventListener("pointermove", onMove);
264	    window.addEventListener("pointerup", onUp, { once: true });
265	    window.addEventListener("pointercancel", onUp, { once: true });
266	    return () => {
267	      window.removeEventListener("pointermove", onMove);
268	      window.removeEventListener("pointerup", onUp);
269	      window.removeEventListener("pointercancel", onUp);
270	    };
271	    // eslint-disable-next-line react-hooks/exhaustive-deps
272	  }, [drag?.id]);
273	
274	  const rankOf = (id: string) => rows.findIndex((r) => r.req.id === id) + 1;
275	
276	  const counts = useMemo(() => {
277	    const c = Object.fromEntries(CATEGORIES.map((k) => [k, 0])) as Record<Category, number>;
278	    rows.forEach((r) => (c[r.req.category] += 1));
279	    return c;
280	  }, [rows]);
281	
282	  const visible = rows.filter(
283	    (r) =>
284	      (category === "All" || r.req.category === category) &&
285	      (urgency === "all" || r.urgency === urgency) &&
286	      (!backedOnly || signalsByTitle.has(r.req.title)) &&
287	      (!focus || focusTitles.has(r.req.title)) &&
288	      (showHidden || !r.scored.hidden),
289	  );
290	  const hiddenCount = rows.filter((r) => r.scored.hidden).length;
291	  const wishlist = useMemo(() => signals.filter((sg) => decisions[sg.id]?.action === "wish"), [signals, decisions]);
292	  const kept = useMemo(() => rows.filter((r) => decisions[r.req.id]?.action === "keep").map((r) => r.req), [rows, decisions]);
293	  const rejectedCount = rows.filter((r) => decisions[r.req.id]?.action === "reject").length;
294	  const open = rows.length - kept.length - rejectedCount;
295	
296	  const profiles = useMemo(
297	    () => (kept.length >= MIN_KEPT_TO_BUILD ? buildProfiles(kept, cfg, scope, fallback, null, wishlist, signals) : []),
298	    [kept, cfg, scope, fallback, wishlist, signals],
299	  );
300	
301	  /* Built: save the generation and open its dashboard. The pipeline's job ends here. */
302	  const finishBuild = useCallback(() => {
303	    const id = newSessionId();
304	    saveSession({
305	      id,
306	      createdAt: new Date().toISOString(),
307	      createdBy: currentUser().name,
308	      createdByRole: currentUser().role,
309	      scope,
310	      scopeLabel,
311	      series: cfg.id,
312	      seriesName: cfg.name,
313	      slug: cfg.slug,
314	      profiles,
315	      decisions,
316	      order: rows.map((r) => r.req.id),
317	      campaigns: null,
318	    });
319	    router.push(generationHref(id));
