---
     1	/* POST /api/scoring-advice  { text, current }  →  ScoringAdvice
     2	 * Turns a manager's instruction into proposed scoring settings. The model only proposes; the UI applies after review.
     3	 * Key: OPENAI_API_KEY from the environment, or (local dev) the git-ignored repo-root .env. Without a key: keyword fallback.
     4	 */
     5	import fs from "node:fs";
     6	import path from "node:path";
     7	import { DEFAULT_SCORING, type ScoringSettings } from "@/lib/pipeline/scoring";
     8	import { adviseByRules, clampSettings, type ScoringAdvice } from "@/lib/pipeline/scoring-advice";
     9	
    10	const MODELS = [process.env.OPENAI_MODEL_FAST, "gpt-6-luna", "gpt-5-mini", "gpt-4.1-mini"].filter(Boolean) as string[];
    11	
    12	function apiKey(): string | null {
    13	  if (process.env.OPENAI_API_KEY) return process.env.OPENAI_API_KEY;
    14	  try {
    15	    const env = fs.readFileSync(path.join(process.cwd(), "..", ".env"), "utf-8");
    16	    const m = env.match(/^\s*(?:export\s+)?OPENAI_API_KEY\s*=\s*["']?([^"'\n#]+)/m);
    17	    return m ? m[1].trim() : null;
    18	  } catch {
    19	    return null;
    20	  }
    21	}
    22	
    23	const SYSTEM = `You tune the scoring of Dixi, a tool that ranks customer feature requests for the next BMW model.
    24	Score = weighted mean of demand (customers asking), market backing (competitors and trends) and principle fit (BMW principles),
    25	then decision memory: a past reject lowers the score by rejectPenalty × strength, strength = 0.5^(days/halfLifeDays);
    26	if demand grew by at least resurfaceAt since the reject, the penalty is lifted; a past keep adds 10 × keepBonus × strength points.
    27	hideRejected hides past rejects instead of ranking them lower; memoryScope is "market" (same market only) or "all".
    28	Ranges: wDemand, wBacking, wFit, rejectPenalty, keepBonus in 0–1; halfLifeDays 30–1095; resurfaceAt 0.1–1.5 (0.3 = +30%).
    29	Change only what the manager's instruction implies; keep everything else as in the current settings.
    30	The settings apply to every series and market. If the instruction names one series or market, say in the summary that the change applies to all of them.
    31	Return JSON only. "changes": one short plain-English sentence per changed setting saying old → new and why. "summary": one or two sentences.`;
    32	
    33	const SCHEMA = {
    34	  name: "scoring_advice",
    35	  strict: true,
    36	  schema: {
    37	    type: "object",
    38	    additionalProperties: false,
    39	    required: ["settings", "changes", "summary"],
    40	    properties: {
    41	      settings: {
    42	        type: "object",
    43	        additionalProperties: false,
    44	        required: ["wDemand", "wBacking", "wFit", "rejectPenalty", "keepBonus", "halfLifeDays", "resurfaceAt", "hideRejected", "memoryScope"],
    45	        properties: {
    46	          wDemand: { type: "number" },
    47	          wBacking: { type: "number" },
    48	          wFit: { type: "number" },
    49	          rejectPenalty: { type: "number" },
    50	          keepBonus: { type: "number" },
    51	          halfLifeDays: { type: "number" },
    52	          resurfaceAt: { type: "number" },
    53	          hideRejected: { type: "boolean" },
    54	          memoryScope: { type: "string", enum: ["market", "all"] },
    55	        },
    56	      },
    57	      changes: { type: "array", items: { type: "string" } },
    58	      summary: { type: "string" },
    59	    },
    60	  },
    61	};
    62	
    63	export async function POST(request: Request) {
    64	  let body: { text?: unknown; current?: Partial<ScoringSettings> };
    65	  try {
    66	    body = await request.json();
    67	  } catch {
    68	    return Response.json({ error: "Invalid JSON" }, { status: 400 });
    69	  }
    70	  const text = typeof body.text === "string" ? body.text.trim().slice(0, 1000) : "";
    71	  if (text.length < 3) return Response.json({ error: "Write an instruction first." }, { status: 400 });
    72	  const current = clampSettings(body.current ?? {}, DEFAULT_SCORING);
    73	
    74	  const key = apiKey();
    75	  if (!key) return Response.json(adviseByRules(text, current) satisfies ScoringAdvice);
    76	
    77	  for (const model of MODELS) {
    78	    try {
    79	      const res = await fetch("https://api.openai.com/v1/chat/completions", {
    80	        method: "POST",
    81	        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    82	        body: JSON.stringify({
    83	          model,
    84	          messages: [
    85	            { role: "system", content: SYSTEM },
    86	            { role: "user", content: `Current settings: ${JSON.stringify(current)}\nManager's instruction: ${text}` },
    87	          ],
    88	          response_format: { type: "json_schema", json_schema: SCHEMA },
    89	        }),
    90	      });
    91	      if (res.status === 404 || res.status === 400) {
    92	        console.warn("[scoring-advice]", model, res.status, (await res.text()).slice(0, 300));
    93	        continue; // model not available: try the next one
    94	      }
    95	      if (!res.ok) break;
    96	      const data = await res.json();
    97	      const parsed = JSON.parse(data.choices?.[0]?.message?.content ?? "{}");
    98	      const advice: ScoringAdvice = {
    99	        settings: clampSettings(parsed.settings ?? {}, current),
   100	        changes: Array.isArray(parsed.changes) ? parsed.changes.slice(0, 9).map(String) : [],
   101	        summary: String(parsed.summary ?? ""),
   102	        source: "ai",
   103	        model,
   104	      };
   105	      return Response.json(advice);
   106	    } catch (e) {
   107	      console.warn("[scoring-advice]", model, String(e).slice(0, 200));
   108	      /* network or parse error: try the next model, then fall back */
   109	    }
   110	  }
   111	  return Response.json(adviseByRules(text, current) satisfies ScoringAdvice);
   112	}

